/**
 * Power Market OS · 电力市场知识课程数据
 * ============================================================================
 *
 * 文件作用：
 *  这是知识库的基础数据模块。CURRICULUM 数组按「章 → 节 → 概念」三级组织
 *  电力市场知识，LEARNING_PATH 给零基础读者的推荐阅读顺序。后续任务（5-8）
 *  会向本数组的 CURRICULUM 追加第 3-13 章；任务 9 的 KnowledgeBook.vue 渲染本文件。
 *
 * 编码方案（本文件固化，后续章节沿用）：
 *  - 章 code：1-2 位数字，'1'..'9' 单位、'10'..'13' 两位（'1' 电力市场全景、'2' 市场主体、'3' 交易品种…）
 *  - 节 code：章 code + 节内序号，2-3 位，如 '11'、'21'…'26'、'101'
 *  - 概念 code：章 code + 节内序号(1 位) + 节内概念序号(1 位)，恒为 3 位以上：
 *      章 1-9 → 3 位（如 '111'、'211'、'263'），章 10-13 → 4 位（如 '1011'、'1311'）。
 *      单概念节的节内概念序号用 '1'：第 1 章每节唯一概念 → '111'/'121'/'131'/'141'/'151'；
 *      多概念节按序编号：第 2 章第 5 节 → '251'/'252'/'253'。
 *  - 冲突规避：概念 code 永远 ≥ 3 位，章 code 永远 ≤ 2 位 → 两者永不相等；
 *      prereq/related 只能引用概念 code（≥3 位），不得引用节 code（2-3 位）。
 *  - 与后端 backend/app/knowledge/categories.py 的子节点编码（211=火电 等）保持一致，
 *    便于交叉检索；本前端模块独立维护，不依赖后端。
 *
 * 字段约定（Concept）：
 *  - prereq  : 前置概念/章 code 数组，支持渐进式学习
 *  - tldr    : 一句话懂了，零术语，开头点生活类比
 *  - analogy : 生活类比 + 折回电力
 *  - definition: 大白话在前，术语在后；术语首次出现给一句话白话释义，缩写展开
 *  - keyPoints: 大白话要点，不是术语堆砌
 *  - compare : 易混对比，维度用日常词（"像什么/谁定价格/什么时候谈"）
 *  - link2sim: "打开交易终端 → …你会看到…"，落到 /trade 的真实市场
 *  - related : 概念 code 交叉引用
 *
 * 交易终端真实市场 key（来自 frontend/src/views/trade/Terminal.vue 的 marketMeta）：
 *  mid_long_term(中长期)、day_ahead(日前)、realtime(实时)、freq(调频辅助服务)、green(绿色电力)
 * ============================================================================
 */

